<script setup>
import AppShell from'../../Layouts/AppShell.vue';import StateCard from'../../Components/StateCard.vue';import PageHeader from'../../Components/PageHeader.vue';import UiAlert from'../../Components/UiAlert.vue';import UiButton from'../../Components/UiButton.vue';import UiModal from'../../Components/UiModal.vue';import{Head,router,useForm}from'@inertiajs/vue3';import{computed,onBeforeUnmount,onMounted,ref,watch}from'vue';
const props=defineProps({event:Object,purpose:String,consentVersion:String,minorEnabled:Boolean,consent:Object,subject:Object,deletion:Object});const accepted=ref(false),adult=ref(false),file=ref(null),preview=ref(null),input=ref(null),timer=ref(),dialog=ref(null),privacyBusy=ref(false);const consentForm=useForm({accepted:false,is_minor:false,privacy_notice_version:props.consentVersion}),selfieForm=useForm({consent_uuid:props.consent?.uuid,selfie:null});const activeConsent=computed(()=>props.consent?.state==='granted'&&props.consent?.privacy_notice_version===props.consentVersion),processing=computed(()=>['queued','processing'].includes(props.subject?.state));const dialogs={cancel:['Cancel search?','Your temporary selfie will be deleted and no result will be released.'],withdraw:['Withdraw consent?','Future biometric processing will stop. Your temporary selfie and personalized results may be removed.'],erase:['Delete event biometric data?','Event-specific biometric records and personalized results will be removed through the secure deletion process.']};
function clearFile(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value=null;file.value=null;selfieForm.selfie=null;if(input.value)input.value.value=''}function choose(e){clearFile();const next=e.target.files?.[0];if(!next)return;file.value=next;selfieForm.selfie=next;preview.value=URL.createObjectURL(next)}function grant(){if(!accepted.value||(!props.minorEnabled&&!adult.value))return;consentForm.accepted=accepted.value;consentForm.is_minor=!adult.value;consentForm.post(`/groups/${props.event.id}/biometric-consents`,{onSuccess:()=>router.reload({only:['consent']})})}function submit(){selfieForm.consent_uuid=props.consent.uuid;selfieForm.post(`/groups/${props.event.id}/face-searches`,{forceFormData:true,onSuccess:()=>{clearFile();router.reload({only:['subject']})}})}function confirmPrivacy(){privacyBusy.value=true;const done=()=>{privacyBusy.value=false;dialog.value=null;router.reload()};if(dialog.value==='cancel')router.post(`/face-searches/${props.subject.uuid}/cancel`,{},{onFinish:done});if(dialog.value==='withdraw')router.delete(`/biometric-consents/${props.consent.uuid}`,{onFinish:done});if(dialog.value==='erase')router.post('/biometric-deletion-requests',{scope:'event',group_id:props.event.id},{onFinish:done})}onMounted(()=>{timer.value=setInterval(()=>{if(processing.value||['queued','processing'].includes(props.deletion?.state))router.reload({only:['subject','deletion'],preserveScroll:true})},2500)});onBeforeUnmount(()=>{clearInterval(timer.value);clearFile()});watch(()=>props.subject?.state,s=>{if(s==='completed')clearFile()});
</script>
<template><AppShell><Head title="Find My Photos"/><div class="lp-page-narrow"><PageHeader eyebrow="Consent-led discovery" :title="`Find My Photos · ${event.name}`" description="Similarity matching can be incorrect. You remain in control and can reject individual results, withdraw consent, or request deletion."/><UiCard v-if="!activeConsent" class="mt-8"><h2 class="text-xl font-bold">Your biometric choice</h2><UiAlert class="mt-4"><b>Purpose:</b> {{purpose}}</UiAlert><p class="lp-help mt-3">Consent notice version {{consentVersion}}. This consent is separate from joining the event.</p><label class="mt-6 flex gap-3 text-sm"><input v-model="accepted" type="checkbox" class="accent-indigo">I explicitly consent to this biometric purpose.</label><label class="mt-4 flex gap-3 text-sm"><input v-model="adult" type="checkbox" class="accent-indigo">I confirm I am not a minor.</label><div class="mt-6 flex flex-wrap gap-3"><UiButton :disabled="!accepted||(!minorEnabled&&!adult)" :loading="consentForm.processing" @click="grant">Grant consent</UiButton><UiButton variant="secondary" :href="`/groups/${event.id}`">Continue without My Photos</UiButton></div><UiAlert v-if="!minorEnabled" tone="warning" class="mt-5">Biometric processing for minors is disabled.</UiAlert></UiCard><section v-else class="mt-8 space-y-6"><UiCard v-if="!subject||['failed','cancelled'].includes(subject.state)"><h2 class="text-xl font-bold">Submit a private selfie</h2><p class="lp-subtitle">Use one clearly visible face. The temporary selfie is deleted after processing, failure or cancellation.</p><input ref="input" class="mt-5 block w-full text-sm" type="file" accept="image/jpeg,image/png,image/webp" capture="user" @change="choose"><div v-if="preview" class="mt-5 flex items-center gap-4"><img :src="preview" alt="Temporary selfie preview" class="h-28 w-28 rounded-xl object-cover"><UiButton variant="secondary" @click="clearFile">Remove</UiButton></div><UiButton class="mt-5" :disabled="!file" :loading="selfieForm.processing" @click="submit">Submit selfie</UiButton></UiCard><StateCard v-if="processing" loading title="Finding your moments" message="We’re securely preparing your results. You may leave this page and return later."><UiButton variant="secondary" class="mt-5" @click="dialog='cancel'">Cancel and delete selfie</UiButton></StateCard><StateCard v-else-if="subject?.outcome==='no_face'" tone="error" title="No face detected" message="Retake your selfie in even light with your face clearly visible."/><StateCard v-else-if="subject?.outcome==='multiple_faces'" tone="error" title="More than one face detected" message="Please submit a selfie containing only you."/><StateCard v-else-if="subject?.state==='failed'" tone="error" title="Search failed safely" message="No result was made available and your temporary selfie was deleted."/><UiCard v-else-if="subject?.state==='completed'"><h2 class="text-xl font-bold">Search completed</h2><UiButton :href="`/face-searches/${subject.uuid}/results`" class="mt-4">View My Photos</UiButton></UiCard><UiCard><h2 class="text-lg font-bold">Privacy controls</h2><p class="lp-subtitle">Withdrawal stops future use. A deletion request removes event-specific biometric records through the secure deletion process.</p><div class="mt-5 flex flex-wrap gap-3"><UiButton variant="secondary" @click="dialog='withdraw'">Withdraw consent</UiButton><UiButton variant="danger" @click="dialog='erase'">Request complete deletion</UiButton></div><UiBadge v-if="deletion" :tone="deletion.state==='completed'?'success':'warning'" class="mt-4">Deletion: {{deletion.state}}</UiBadge></UiCard></section><UiModal :open="!!dialog" :title="dialogs[dialog]?.[0]" :description="dialogs[dialog]?.[1]" :busy="privacyBusy" @close="dialog=null" @confirm="confirmPrivacy"/></div></AppShell></template>
